source.exploreUrl:
@js:
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});
$$ = (second_channel, status) => `/fiction/search/channel,{"method": "POST","body": "app=midu&second_channel=${second_channel}&status=${status}&page={{page-1}\}&rank="}`;
[
    [
        ["玄幻", 3],
        ["都市", 5],
        ["推理", 7],
        ["仙侠", 15],
        ["科幻", 27],
        ["游戏", 30],
        ["武侠", 32],
        ["历史", 35],
        ["奇幻", 39],
        ["军事", 93],
        ["体育", 47],
        ["现实", 79],
        ["同人", 61]
    ],
    [
        ["现代言情", 13],
        ["古代言情", 17],
        ["悬疑刑侦", 24],
        ["玄幻仙侠", 41],
        ["青春校园", 51],
        ["同人小说", 68],
        ["科幻空间", 78],
        ["游戏竞技", 95]
    ]
].map((Arr, isN) => {
    push("༺ˇ»`ʚ " + (isN ? "女" : "男") + "频 ɞ´«ˇ༻", null, 1);
    Arr.map([title, second_channel] => {
        ["[" + title + "]", "完结", "连载"].map((title, status) => {
            push(title, $$(second_channel, status), 0.25);
        });
    });
});
JSON.stringify(sort);

